      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
        { label: "Right", value: "right" },
      ],
    },
    overlay: {
      type: "select" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Scrim", value: "scrim" },
        { label: "Gradient ↓", value: "gradient down" },
        { label: "Gradient →", value: "gradient right" },
      ],
    },
    overlayStrength: {
      type: "select" as const,
      options: [
        { label: "Light", value: "light" },
        { label: "Medium", value: "medium" },
        { label: "Heavy", value: "heavy" },
      ],
    },
    knockout: {
      type: "radio" as const,
      options: [
        { label: "Off", value: "off" },
        { label: "On", value: "on" },
      ],
    },
  },
  defaultProps: {
    eyebrow: "New — now available",
    title: "Your big idea, beautifully online.",
    description:
      "A flexible starting point for your next page. Swap in your own headline, story, and imagery — this layout adapts to whatever you publish.",
    primaryLabel: "Start free trial",
    secondaryLabel: "Book a demo →",
    tone: "accent",
    layout: "split",
    imageSrc: wireframe(1200, 675),
    imageSide: "right",
    imageFill: "card",
    splitRatio: "even",
    align: "left",
    overlay: "gradient right",
    overlayStrength: "medium",
    knockout: "off",
  },
  render: HeroRender,
};

export const meta = defineMeta({
  title: 'Hero',
  description: 'Large page hero with eyebrow, title, description, two CTA buttons, and an image in split/full-image/text-only layouts with overlay options.',
  categories: ["attention"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-btn"],
});

.p1-hero {
  overflow: hidden;
  position: relative;
}

/* ── Tone backgrounds (split + text-only) ─────────── */
.p1-hero[data-tone="accent"] { background-color: var(--p1-accent); }
.p1-hero[data-tone="dark"] { background-color: var(--p1-surface-dark); }
.p1-hero[data-tone="light"] { background-color: var(--p1-surface-subtle); }

/* ── Full-image layout ───────────────────────────── */
.p1-hero[data-layout="full-image"] {
  align-items: center;
  background-color: var(--p1-surface-dark);
  display: grid;
  min-block-size: 29rem;
  padding-block: var(--p1-space-3xl);
  padding-inline: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-hero[data-layout="full-image"] {
    min-block-size: 34rem;
    padding-block: 6rem;
    padding-inline: 2.5rem;
  }
}
@media (width >= 64rem) {
  .p1-hero[data-layout="full-image"] { padding-inline: var(--p1-space-3xl); }
}

.p1-hero__bg-img {
  block-size: 100%;
  inline-size: 100%;
  inset: 0;
  object-fit: cover;
  position: absolute;
  z-index: 0;
}

.p1-hero__overlay {
  inset: 0;
  position: absolute;
  z-index: 1;
}

.p1-hero__fullimg-content {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
  position: relative;
  z-index: 2;
}
.p1-hero__fullimg-content[data-align="center"] { display: flex; justify-content: center; }
.p1-hero__fullimg-content[data-align="right"] { display: flex; justify-content: end; }

/* ── Text-only layout ────────────────────────────── */
.p1-hero[data-layout="text-only"] {
  padding-block: 5rem;
  padding-inline: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-hero[data-layout="text-only"] { padding-block: 6rem; padding-inline: 2.5rem; }
}
@media (width >= 64rem) {
  .p1-hero[data-layout="text-only"] { padding-inline: var(--p1-space-3xl); }
}

.p1-hero__text-content {
  display: flex;
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}
.p1-hero__text-content[data-align="center"] { justify-content: center; }
.p1-hero__text-content[data-align="right"] { justify-content: end; }

/* ── Split layout ────────────────────────────────── */
.p1-hero[data-layout="split"] {
  padding-block: var(--p1-space-3xl);
  padding-inline: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-hero[data-layout="split"] { padding-block: 5rem; padding-inline: 2.5rem; }
}
@media (width >= 64rem) {
  .p1-hero[data-layout="split"] { padding-inline: var(--p1-space-3xl); }
}

.p1-hero__split-grid {
  align-items: center;
  display: grid;
  gap: var(--p1-space-lg);
  grid-template-columns: 1fr;
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}
@media (width >= 48rem) {
  .p1-hero__split-grid {
    gap: 3.5rem;
    grid-template-columns: var(--p1-hero-split-cols, 1fr 1fr);
  }
}

.p1-hero__copy-wrap { display: flex; align-items: center; }

/* Flush image */
.p1-hero[data-imagefill="flush"] .p1-hero__split-grid {
  align-items: stretch;
  gap: 0;
  max-inline-size: 100%;
  padding: 0;
}
.p1-hero[data-imagefill="flush"] .p1-hero__copy-wrap {
  padding-block: 3.5rem;
  padding-inline: var(--p1-space-lg);
}
@media (width >= 48rem) {
  .p1-hero[data-imagefill="flush"] .p1-hero__copy-wrap {
    padding-block: 5rem;
    padding-inline: 2.5rem;
  }
}
@media (width >= 64rem) {
  .p1-hero[data-imagefill="flush"] .p1-hero__copy-wrap { padding-inline: var(--p1-space-3xl); }
}

.p1-hero__img-flush {
  min-block-size: 17.5rem;
  overflow: hidden;
  position: relative;
}
@media (width >= 48rem) {
  .p1-hero__img-flush { min-block-size: 27.5rem; }
}

.p1-hero__img-flush .p1-hero__img {
  block-size: 100%;
  inline-size: 100%;
  inset: 0;
  object-fit: cover;
  position: absolute;
}

/* Card image */
.p1-hero__img-card {
  border-radius: 1rem;
  overflow: hidden;
}
.p1-hero[data-tone="light"] .p1-hero__img-card {
  border: 1px solid var(--p1-border);
}
.p1-hero[data-tone="accent"] .p1-hero__img-card,
.p1-hero[data-tone="dark"] .p1-hero__img-card {
  border: 1px solid var(--p1-border-inverse);
  background-color: var(--p1-input-inverse-bg);
}

.p1-hero__img-card .p1-hero__img {
  aspect-ratio: 4 / 3;
  block-size: 100%;
  display: block;
  inline-size: 100%;
  object-fit: cover;
}

/* ── Copy block ─────────────────────────────────── */
.p1-hero__copy {
  inline-size: 100%;
}
.p1-hero__copy[data-align="center"] { text-align: center; margin-inline: auto; max-inline-size: 47.5rem; }
.p1-hero__copy[data-align="right"] { text-align: end; max-inline-size: 35rem; margin-inline-start: auto; }
.p1-hero__copy[data-align="left"] { max-inline-size: 35rem; }

.p1-hero__eyebrow {
  align-items: center;
  border-radius: var(--p1-radius-pill);
  border: 1px solid;
  display: inline-flex;
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-medium);
  gap: 0.5rem;
  margin-block-end: var(--p1-space-md);
  padding: 0.375rem 1rem;
}
.p1-hero__copy[data-ondark="true"] .p1-hero__eyebrow {
  border-color: var(--p1-border-inverse-strong);
  background-color: var(--p1-border-inverse);
  color: var(--p1-fg-inverse);
}
.p1-hero__copy:not([data-ondark]) .p1-hero__eyebrow {
  border-color: var(--p1-border);
  background-color: var(--p1-surface-default);
  color: var(--p1-fg-default);
}

.p1-hero__title {
  font-size: clamp(1.875rem, 5vw, 3.75rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.02;
  text-wrap: balance;
}
.p1-hero__copy[data-ondark="true"] .p1-hero__title { color: var(--p1-fg-inverse); }
.p1-hero__copy:not([data-ondark]) .p1-hero__title { color: var(--p1-fg-default); }

.p1-hero__desc {
  font-size: var(--p1-text-base);
  line-height: var(--p1-leading-relaxed);
  margin-block-start: var(--p1-space-md);
  max-inline-size: 36rem;
}
.p1-hero__copy[data-align="center"] .p1-hero__desc { margin-inline: auto; }
.p1-hero__copy[data-align="right"] .p1-hero__desc { margin-inline-start: auto; }
.p1-hero__copy[data-ondark="true"] .p1-hero__desc { color: var(--p1-fg-inverse-subtle); }
.p1-hero__copy:not([data-ondark]) .p1-hero__desc { color: var(--p1-fg-muted); }
@media (width >= 40rem) {
  .p1-hero__desc { font-size: var(--p1-text-lg); }
}

.p1-hero__actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--p1-space-sm);
  margin-block-start: var(--p1-space-lg);
}
.p1-hero__actions[data-align="center"] { justify-content: center; }
.p1-hero__actions[data-align="right"] { justify-content: end; }

.p1-hero__secondary {
  align-items: center;
  border-radius: var(--p1-radius-pill);
  border: 1px solid;
  display: inline-flex;
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  padding: 0.75rem 1.5rem;
}
.p1-hero__copy[data-ondark="true"] .p1-hero__secondary {
  border-color: var(--p1-border-inverse-strong);
  color: var(--p1-fg-inverse);
}
.p1-hero__copy:not([data-ondark]) .p1-hero__secondary {
  border-color: var(--p1-border);
  color: var(--p1-fg-default);
}

